WITH src AS (SELECT * FROM payments WHERE NOT (order_id = 25 AND (order_id IN (8, 28, 34, 37) OR TO_DATE(paid_at) < '2024-10-01'))), status_summary AS (SELECT status, method, MIN(paid_at) AS min_paid_at, COUNT(DISTINCT amount) AS unique_statuss FROM src GROUP BY status, method) SELECT status, min_paid_at, unique_statuss FROM status_summary WHERE unique_statuss < 3 ORDER BY unique_statuss DESC
